#!/usr/bin/env python3
"""Run C1 Unit02 recalibration with narrow depth extensions that avoid new target forms."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c1_unit02.py')
text=SOURCE.read_text(encoding='utf-8')
patches={
"وفي نهاية المراجعة لم يعد السؤال من «صاحب الجواب النهائي؟» بل «هل جمعت المؤسسة أنواع المعرفة اللازمة للقرار، وهل يمكن للقارئ أن يرى أين تنتهي كل واحدة منها؟».''',":"وفي نهاية المراجعة لم يعد السؤال من «صاحب الجواب النهائي؟» بل «هل جمعت المؤسسة أنواع المعرفة اللازمة للقرار، وهل يمكن للقارئ أن يرى أين تنتهي كل واحدة منها؟». وأضافوا مراجعة لاحقة بعد تنفيذ التوصية بثلاثة أسابيع، لاختبار ما إذا كانت الافتراضات التي قدمها كل تخصص بقيت صحيحة عند التطبيق. فإذا تغيرت الظروف أو ظهر أثر لم يتوقعه أحد، يعود السؤال إلى الجهة القادرة على تفسيره بدل أن يُدمج تلقائيًا في حكم قديم. بهذا صار توزيع المعرفة قابلًا للتحديث مع تغير الواقع، لا مجرد خريطة ثابتة كتبت يوم الاجتماع الأول.''',",
"بهذا صار القرار التدريجي وسيلة لجمع معلومات عن الفائدة وعن قابلية الإصلاح معًا، لا مجرد طريقة لإرضاء الفريقين اللذين يريد أحدهما السرعة ويريد الآخر التأجيل.''',":"بهذا صار القرار التدريجي وسيلة لجمع معلومات عن الفائدة وعن قابلية الإصلاح معًا، لا مجرد طريقة لإرضاء الفريقين اللذين يريد أحدهما السرعة ويريد الآخر التأجيل. كما طلبت ندى من شخص لم يشارك في تصميم الاختبار قراءة سجل القرارات ومحاولة تحديد سبب كل توسع أو توقف. عجز عن تفسير قرار واحد لأن الفريق لم يكتب الدليل الذي اعتمد عليه، فأضافوا شرطًا توثيقيًا: لا تنتقل المرحلة إلا إذا أمكن لشخص مستقل إعادة بناء منطقها من السجل. جعل ذلك التعلم الناتج عن الاختبار قابلًا للنقل إلى فريق آخر، لا معرفة ضمنية تبقى عند من نفذه فقط.''',",
"المطلوب بناء عملية تجعل أثر المصالح المحتمل قابلًا للرؤية والتحدي حتى لو كان كل رقم منفرد في الجدول صحيحًا.''',":"المطلوب بناء عملية تجعل أثر المصالح المحتمل قابلًا للرؤية والتحدي حتى لو كان كل رقم منفرد في الجدول صحيحًا. وأضافت اللجنة سجلًا للتغييرات يبين متى أضيف معيار أو حُذف بديل ومن اقترح التعديل وما السبب المعلن. لم يفترضوا أن كل تعديل مشبوه، لكنهم أرادوا منع إعادة تشكيل التحليل تدريجيًا من دون أن يلاحظ أصحاب القرار ذلك. وعندما أعيدت المراجعة بعد شهر، استطاع عضو جديد أن يرى أي الاختيارات كانت فنية وأيها كانت تقديرية، وأن يطلب دليلاً إضافيًا فقط عند النقاط التي تحمل الحكم الأكبر.''',",
"قالت سارة إن العمل بين التخصصات يصبح ناضجًا عندما يتحول اختلاف منظور الأقسام إلى بنية اختبار ومراجعة، لا إلى مساومة سياسية يعطي فيها كل فريق جزءًا من طلبه ليخرج الاجتماع بهدوء.''',":"قالت سارة إن العمل بين التخصصات يصبح ناضجًا عندما يتحول اختلاف منظور الأقسام إلى بنية اختبار ومراجعة، لا إلى مساومة سياسية يعطي فيها كل فريق جزءًا من طلبه ليخرج الاجتماع بهدوء. ولمنع هيمنة القسم الأكبر، جعلت عرض المؤشرات يبدأ بالهدف المشترك ثم يبين ما يضيفه كل تخصص إلى فهمه، لا بترتيب أصحاب المناصب. كما طلبت أن يذكر كل فريق نقطة يمكن لدليل جديد أن تغير رأيه فيها. كشف هذا الشرط المواقف التي كانت قابلة للتعلم وتلك التي تحولت إلى دفاع مؤسسي لا تحدده ملاحظة ممكنة.''',",
"المهم أن يكون الخروج قابلًا للتبرير، وأن تكشف البيانات متى يصبح الاستثناء المتكرر معرفة ينبغي أن تدخل في تصميم القاعدة نفسها.''',":"المهم أن يكون الخروج قابلًا للتبرير، وأن تكشف البيانات متى يصبح الاستثناء المتكرر معرفة ينبغي أن تدخل في تصميم القاعدة نفسها. كما راقب الفريق الزمن الذي تستغرقه المراجعة، لأن مسارًا دقيقًا جدًا لكنه بطيء قد يدفع الموظفين إلى تجاوزه في الحالات العاجلة. خففوا المتطلبات في الحالات منخفضة الأثر وأبقوا التوثيق الأوسع للقرارات التي تغير ترتيبًا مهمًا. بذلك صار مقدار الإجراء متناسبًا مع أثر القرار، وبقيت المساءلة موجودة من دون أن تتحول إلى عبء يجعل القناة الرسمية أقل استخدامًا من الطرق غير المسجلة.''',",
"وقالت إن الحكم المهني القابل للتفسير لا يعني أن كل قرار سيقنع الجميع، بل أن الخلاف يستطيع أن يتجه إلى دليل أو قيمة أو مسؤولية محددة بدل أن يبقى اعتراضًا على مكانة صاحب القرار.''',":"وقالت إن الحكم المهني القابل للتفسير لا يعني أن كل قرار سيقنع الجميع، بل أن الخلاف يستطيع أن يتجه إلى دليل أو قيمة أو مسؤولية محددة بدل أن يبقى اعتراضًا على مكانة صاحب القرار. وفي تمرين أخير أعطت الفريق قرارًا سابقًا من دون اسم صاحبه وطلبت منهم تقييم منطقه من السجل فقط. اختلفت آراؤهم في بعض الأوزان، لكنهم استطاعوا تحديد موضع الاختلاف بدقة واقتراح معلومات كان يمكن أن تحسم جزءًا منه. رأت هدى أن هذا هو الاختبار العملي للجودة: أن يبقى القرار مفهومًا وقابلًا للنقد حتى بعد خروج صاحبه من الغرفة.''',",
}
for old,new in patches.items():
    assert text.count(old)==1, f'expected one retry insertion point: {old[:40]!r}'
    text=text.replace(old,new)
exec(compile(text,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
